export type PageViewEvent = {
  path: string
  userAgent: string | null
}

/**
 * Sends a page view to your analytics backend. Safe to call from `after()`;
 * failures are swallowed so they never affect the user-facing response.
 */
export async function logPageView(event: PageViewEvent): Promise<void> {
  const endpoint = process.env.ANALYTICS_INGEST_URL

  if (endpoint) {
    try {
      await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'page_view',
          ...event,
          recordedAt: new Date().toISOString(),
        }),
        signal: AbortSignal.timeout(10_000),
      })
    } catch {
      // Intentionally ignore: analytics must not surface errors to users.
    }
    return
  }

  if (process.env.NODE_ENV === 'development') {
    console.info('[analytics] page_view', event)
  }
}

